param([switch]$NoBrowser)
$ErrorActionPreference='Stop'
$project='C:\Projects\gympro-api'
$prepared='C:\Projects\gympro-backups\fresh-install-20261025224743_7fb515'
$clean=Join-Path $prepared 'source';$cluster=Join-Path $prepared 'pgdata'
$report=Join-Path 'C:\Projects\gympro-backups' ('fresh-install-resume-'+(Get-Date -Format 'yyyyMMddHHmmss')+'_'+[guid]::NewGuid().ToString('N').Substring(0,6))
$bin='C:\Program Files\PostgreSQL\18\bin';$started=$false;$success=$false;$savedEnv=@{};$envCaptured=$false
function Run([string]$Exe,[string[]]$Arguments,[string]$Step){Write-Host "CHECK: $Step" -ForegroundColor Cyan;$old=$ErrorActionPreference;try{$ErrorActionPreference='Continue';& $Exe @Arguments;$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old};[IO.File]::WriteAllText((Join-Path $report ($Step+'.exit-code.txt')),[string]$code);if($null -eq $code -or $code -ne 0){throw "Step failed: $Step (exit $code)"}}
function Temporary-Password(){while($true){$secure=Read-Host 'Choose a separate temporary account password (12-200 characters)' -AsSecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);try{$v=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr);$secure.Dispose()};if($v.Length -ge 12 -and $v.Length -le 200 -and -not [string]::IsNullOrWhiteSpace($v)){return $v};Write-Host 'Use 12 to 200 characters.'}}
try{
 Set-Location $project
 foreach($step in @('archive-committed-source','npm-ci','prisma-generate','build','initdb','start','createdb','roles','schema','010-permissions','verify-prerequisites','verify-schema','stop')){if((Get-Content (Join-Path $prepared ($step+'.exit-code.txt')) -Raw).Trim() -ne '0'){throw "Prepared installation prerequisite incomplete: $step"}}
 if((Get-Content (Join-Path $cluster 'PG_VERSION') -Raw).Trim() -ne '18'){throw 'Unexpected prepared PostgreSQL version.'}
 $opts=Get-Content (Join-Path $cluster 'postmaster.opts') -Raw
 $match=[regex]::Match($opts,'"-p"\s+"(\d+)"')
 if(-not $match.Success){throw 'Cannot identify the prepared cluster port.'};$port=[int]$match.Groups[1].Value
 if($port -lt 55432 -or $port -gt 55462 -or $opts -notmatch '127\.0\.0\.1'){throw 'Prepared cluster is not the expected loopback rehearsal.'}
 if(Test-Path (Join-Path $cluster 'postmaster.pid')){throw 'Prepared cluster appears running. Stop and inspect it before resuming.'}
 New-Item -ItemType Directory $report | Out-Null
 $payload=Join-Path $report 'payload';$zip=Join-Path $report 'payload.zip';[IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String(''));Expand-Archive $zip $payload
 $review=Get-Content (Join-Path $payload 'readiness-manifest.json') -Raw | ConvertFrom-Json
 $git='C:\Program Files\Git\cmd\git.exe'
 $sourceCommit=(Get-Content (Join-Path $prepared 'source-commit.txt') -Raw).Trim()
 if($sourceCommit -notmatch '^68b9c76[a-f0-9]{33}$'){throw 'Prepared archive is not the expected 68b9c76 checkpoint.'}
 foreach($entry in $review.sourceHashes){
  if((Get-FileHash (Join-Path $project $entry.file) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.sha256){throw "Reviewed working file changed: $($entry.file)"}
 }
 $proofZip=Join-Path $report 'verified-commit-archive.zip'
 Run $git @('-C',$project,'archive','--format=zip',('--output='+$proofZip),$sourceCommit) 'verify-committed-archive'
 Add-Type -AssemblyName System.IO.Compression.FileSystem
 $archive=[IO.Compression.ZipFile]::OpenRead($proofZip)
 $sha=[Security.Cryptography.SHA256]::Create();$repairCount=0
 try{
  foreach($entry in $review.sourceHashes){
   $item=$archive.GetEntry($entry.file)
   if($null -eq $item){throw "Committed archive entry missing: $($entry.file)"}
   $entryStream=$item.Open();$memory=New-Object IO.MemoryStream
   try{$entryStream.CopyTo($memory);$bytes=$memory.ToArray()}finally{$entryStream.Dispose();$memory.Dispose()}
   $hash=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()
   if($entry.file -eq 'sql/baseline-20261016/schema.sql' -and $hash -ne '24765f818899517aaaa79e39fe7269aae201bcaf774ea4faeff3a8948327ce06'){throw 'Committed archive baseline exact-byte checksum mismatch.'}
   $freshFile=Join-Path $clean $entry.file
   $same=(Test-Path $freshFile) -and ((Get-FileHash $freshFile -Algorithm SHA256).Hash.ToLowerInvariant() -eq $hash)
   if(-not $same){
    if(Test-Path $freshFile){$backup=Join-Path (Join-Path $report 'source-before-repair') $entry.file;New-Item -ItemType Directory (Split-Path $backup) -Force | Out-Null;Copy-Item $freshFile $backup}
    New-Item -ItemType Directory (Split-Path $freshFile) -Force | Out-Null
    [IO.File]::WriteAllBytes($freshFile,$bytes);$repairCount++
   }
   if((Get-FileHash $freshFile -Algorithm SHA256).Hash.ToLowerInvariant() -ne $hash){throw "Fresh file differs from trusted archive entry: $($entry.file)"}
  }
 }finally{$archive.Dispose();$sha.Dispose()}
 if((Get-FileHash (Join-Path $clean 'sql\baseline-20261016\schema.sql') -Algorithm SHA256).Hash.ToLowerInvariant() -ne '24765f818899517aaaa79e39fe7269aae201bcaf774ea4faeff3a8948327ce06'){throw 'Baseline exact-byte checksum mismatch.'}
 Write-Host "PASS: Reviewed inputs match a newly generated archive of $sourceCommit; repaired isolated files: $repairCount. Backups retained."
 $adapters=Get-Content (Join-Path $payload 'adapter-manifest.json') -Raw | ConvertFrom-Json
 foreach($entry in $adapters.PSObject.Properties){$dest=Join-Path $clean $entry.Name;New-Item -ItemType Directory (Split-Path $dest) -Force | Out-Null;if(Test-Path $dest){if((Get-FileHash $dest -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.Value){throw "Different lab adapter exists: $($entry.Name)"}}else{Copy-Item (Join-Path $payload $entry.Name) $dest}}
 Copy-Item (Join-Path $clean 'tools\provisioning\provision.mjs') (Join-Path $payload 'provision.mjs')
 $envCaptured=$true
 foreach($item in @(Get-ChildItem Env:)){if($item.Name -match '^(GYMPRO_|PG|PRISMA_|.*DATABASE_URL$|NODE_ENV$|NODE_OPTIONS$|PORT$)'){$savedEnv[$item.Name]=$item.Value;[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}}
 $env:PGSSLMODE='disable';$env:DATABASE_URL='postgresql://gympro_app@127.0.0.1:1/gympro_saas';$env:AUTH_DATABASE_URL='postgresql://gympro_auth@127.0.0.1:1/gympro_saas';$env:SESSION_DATABASE_URL='postgresql://gympro_session@127.0.0.1:1/gympro_saas'
 $node=(Get-Command node.exe -ErrorAction Stop).Source;$npm=(Get-Command npm.cmd -ErrorAction Stop).Source
 Set-Location $clean;Run $npm @('run','build') 'build'
 $apiPort=$null;foreach($candidate in 3151..3181){$l=New-Object Net.Sockets.TcpListener([Net.IPAddress]::Parse('127.0.0.1'),$candidate);try{$l.Start();$apiPort=$candidate;break}catch{}finally{$l.Stop()}};if(-not $apiPort){throw 'No free isolated API port.'}
 $started=$true;Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-l',(Join-Path $report 'server.log'),'-o',"-h 127.0.0.1 -p $port",'-w','start') 'start'
 if($NoBrowser){$env:GYMPRO_1F_PASSWORD=[guid]::NewGuid().ToString('N')+[guid]::NewGuid().ToString('N');$env:GYMPRO_FRESH_NO_BROWSER='1'}else{$env:GYMPRO_1F_PASSWORD=Temporary-Password}
 try{Run $node @((Join-Path $payload 'verify-and-demo.mjs'),$clean,"$port",'gympro_bootstrap_20261025224743_7fb515',"$apiPort",$report) 'full-tests-e2e-and-http'}finally{$env:GYMPRO_1F_PASSWORD=$null;$env:GYMPRO_FRESH_NO_BROWSER=$null}
 $checks=Get-Content (Join-Path $report 'provisioning-results.json') -Raw | ConvertFrom-Json;$unit=Get-Content (Join-Path $report 'full-suite-results.json') -Raw | ConvertFrom-Json;$e2e=Get-Content (Join-Path $report 'root-e2e-results.json') -Raw | ConvertFrom-Json
 if($checks.automaticChecksPassed -ne $true -or $checks.automaticCheckCount -ne 46 -or $checks.fixtureCleanupPassed -ne $true -or $checks.ownApiStopped -ne $true -or $unit.success -ne $true -or $unit.numPassedTests -lt 1567 -or $unit.numPendingTests -ne 0 -or $unit.numFailedTests -ne 0 -or $e2e.success -ne $true){throw 'Test or cleanup evidence incomplete.'};$success=$true
}catch{Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}finally{
 $env:GYMPRO_1F_PASSWORD=$null;$env:GYMPRO_FRESH_NO_BROWSER=$null
 if($started -and (Test-Path (Join-Path $cluster 'postmaster.pid'))){try{Run (Join-Path $bin 'pg_ctl.exe') @('-D',$cluster,'-m','fast','-w','stop') 'stop'}catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}}
 if($envCaptured){foreach($item in @(Get-ChildItem Env:)){if($item.Name -match '^(GYMPRO_|PG|PRISMA_|.*DATABASE_URL$|NODE_ENV$|NODE_OPTIONS$|PORT$)'){[Environment]::SetEnvironmentVariable($item.Name,$null,'Process')}};foreach($key in $savedEnv.Keys){[Environment]::SetEnvironmentVariable($key,$savedEnv[$key],'Process')}}
 Set-Location $project
}
if($success){try{
 $backup=Join-Path $report 'working-adapters-before-install';New-Item -ItemType Directory $backup -Force | Out-Null
 foreach($entry in $adapters.PSObject.Properties){$dest=Join-Path $project $entry.Name;if(Test-Path $dest){if((Get-FileHash $dest -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.Value){throw "Different working adapter exists: $($entry.Name)"}}}
 foreach($entry in $adapters.PSObject.Properties){$dest=Join-Path $project $entry.Name;New-Item -ItemType Directory (Split-Path $dest) -Force | Out-Null;if(Test-Path $dest){Copy-Item $dest (Join-Path $backup (($entry.Name -replace '/','_'))) -Force};Copy-Item (Join-Path $payload $entry.Name) $dest -Force}
 $saved=Join-Path $project 'tools\fresh-install';New-Item -ItemType Directory $saved -Force | Out-Null;Copy-Item (Join-Path $payload 'verify-and-demo.mjs') (Join-Path $saved 'verify-and-demo.mjs') -Force
 Copy-Item (Join-Path $payload 'fresh-install-original.ps1') (Join-Path $project 'scripts\completion-fresh-install.ps1') -Force
 Copy-Item $PSCommandPath (Join-Path $project 'scripts\completion-fresh-install-resume.ps1') -Force
 $head=(Get-Content (Join-Path $prepared 'source-commit.txt') -Raw).Trim()
 [ordered]@{scope='Fresh installation with portable lab test import adapters';sourceCommit=$head;preparedInstall=$prepared;gitArchiveUsed=$true;labAdapterCount=8;labImportAdaptersVerified=$true;allDiscoveredSuitesPassed=$true;testsExcluded=$false;npmCiPreviouslyPassed=$true;prismaGenerationPreviouslyPassed=$true;buildPassed=$true;fullSuitePassed=$true;passedTests=$unit.numPassedTests;skippedTests=$unit.numPendingTests;rootE2ePassed=$true;httpDatabaseChecks=46;fixturesRemoved=$true;ownApiStopped=$true;clusterStopped=$true;manualBrowserAcceptance='pending-user-confirmation';noBrowser=[bool]$NoBrowser;differentMachineVerified=$false;hostedCiVerified=$false;stagingDeploymentVerified=$false;workingDatabaseChanged=$false;productionAppSourceChanged=$false;labToolSourceChanged=$true;adapterFixCommitted=$false;kbzPayDeferred=$true;reportFolder=$report;verifiedAt=(Get-Date -Format o)} | ConvertTo-Json | Set-Content (Join-Path $report 'fresh-install-summary.json') -Encoding UTF8
 Copy-Item (Join-Path $report 'fresh-install-summary.json') (Join-Path $project 'docs\completion\fresh-install-summary.json') -Force
 Write-Host 'PASS: Full discovered suite (no exclusions), root e2e and 46 HTTP/database checks passed; fixtures removed and own API/cluster stopped.' -ForegroundColor Green
 Write-Host 'PASS: Eight stored-lab import adapters installed; production authentication module and working database unchanged.'
 Write-Host 'PENDING: Browser acceptance, checkpoint with adapter fix, different-machine verification, hosted CI and staging.'
}catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}}
Write-Host "Reports: $report";Write-Host "Prepared source/cluster retained: $prepared";Write-Host 'No npm reinstall, schema reinstallation, working database/.env change, production lab activation, Git commit or KBZPay operation.'
if(-not $success){exit 1}
